CREATE TABLE public.bot_products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, category text NOT NULL DEFAULT 'Forex', platform text NOT NULL DEFAULT 'MT5', short_description text NOT NULL DEFAULT '', description text NOT NULL DEFAULT '', price numeric(12,2) NOT NULL DEFAULT 0 CHECK(price > 0), features text[] NOT NULL DEFAULT '{}', instruments text[] NOT NULL DEFAULT '{}', instructions text NOT NULL DEFAULT '', image_url text, published boolean NOT NULL DEFAULT false, available boolean NOT NULL DEFAULT true, deleted boolean NOT NULL DEFAULT false, requires_subscription boolean NOT NULL DEFAULT false, download_limit integer NOT NULL DEFAULT 0 CHECK(download_limit >= 0), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.bot_products TO anon, authenticated; GRANT ALL ON public.bot_products TO service_role;
ALTER TABLE public.bot_products ENABLE ROW LEVEL SECURITY;
CREATE POLICY bot_catalog ON public.bot_products FOR SELECT TO anon,authenticated USING ((published AND NOT deleted) OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.bot_file_metadata (product_id uuid PRIMARY KEY REFERENCES public.bot_products(id), path text NOT NULL, filename text NOT NULL, size_bytes integer NOT NULL, content_type text NOT NULL, uploaded_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.bot_file_metadata TO service_role; ALTER TABLE public.bot_file_metadata ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.bot_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reference text UNIQUE NOT NULL DEFAULT ('BOT-' || upper(substr(replace(gen_random_uuid()::text,'-',''),1,12))), user_id uuid NOT NULL, product_id uuid NOT NULL REFERENCES public.bot_products(id), product_name text NOT NULL, amount numeric(12,2) NOT NULL, currency text NOT NULL DEFAULT 'USD', status text NOT NULL DEFAULT 'awaiting_payment' CHECK(status IN ('awaiting_payment','under_review','paid','rejected','cancelled','refunded')), reason text, created_at timestamptz NOT NULL DEFAULT now(), paid_at timestamptz);
GRANT SELECT ON public.bot_orders TO authenticated; GRANT ALL ON public.bot_orders TO service_role; ALTER TABLE public.bot_orders ENABLE ROW LEVEL SECURITY;
CREATE POLICY bot_orders_read ON public.bot_orders FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE UNIQUE INDEX bot_order_one_open ON public.bot_orders(user_id,product_id) WHERE status IN ('awaiting_payment','under_review','paid');
CREATE TABLE public.bot_payment_submissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid UNIQUE NOT NULL REFERENCES public.bot_orders(id), method_id uuid NOT NULL REFERENCES public.payment_methods(id), method_name text NOT NULL, transaction_reference text NOT NULL, proof_path text, submitted_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.bot_payment_submissions TO service_role; ALTER TABLE public.bot_payment_submissions ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX bot_transaction_unique ON public.bot_payment_submissions(method_id,lower(transaction_reference));
CREATE TABLE public.bot_entitlements (order_id uuid PRIMARY KEY REFERENCES public.bot_orders(id), user_id uuid NOT NULL, product_id uuid NOT NULL REFERENCES public.bot_products(id), revoked boolean NOT NULL DEFAULT false, granted_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.bot_entitlements TO service_role; ALTER TABLE public.bot_entitlements ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.bot_download_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES public.bot_orders(id), user_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.bot_download_logs TO service_role; ALTER TABLE public.bot_download_logs ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.bot_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor uuid, action text NOT NULL, details jsonb, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.bot_audit TO service_role; ALTER TABLE public.bot_audit ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.bot_announcement (id boolean PRIMARY KEY DEFAULT true CHECK(id), enabled boolean NOT NULL DEFAULT true, heading text NOT NULL DEFAULT 'Introducing Get Bot File 🗃️', message text NOT NULL DEFAULT 'Discover specialized Forex trading bots available for individual purchase. Explore product details, compare features, and securely purchase the bot files you need with a one-time payment.', destination text NOT NULL DEFAULT '/get-bot-file');
GRANT SELECT ON public.bot_announcement TO anon,authenticated; GRANT ALL ON public.bot_announcement TO service_role; ALTER TABLE public.bot_announcement ENABLE ROW LEVEL SECURITY;
CREATE POLICY announcement_read ON public.bot_announcement FOR SELECT TO anon,authenticated USING(true);
CREATE OR REPLACE FUNCTION public.create_bot_order(_product uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.bot_products; o uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; SELECT * INTO p FROM public.bot_products WHERE id=_product AND published AND available AND NOT deleted FOR SHARE; IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.bot_file_metadata WHERE product_id=p.id) THEN RAISE EXCEPTION 'Product unavailable'; END IF; IF EXISTS(SELECT 1 FROM public.account_access WHERE user_id=auth.uid() AND suspended) THEN RAISE EXCEPTION 'Account suspended'; END IF; IF p.requires_subscription AND NOT coalesce((public.subscription_entitlement()->>'allowed')::boolean,false) THEN RAISE EXCEPTION 'This product requires an active subscription'; END IF; SELECT id INTO o FROM public.bot_orders WHERE user_id=auth.uid() AND product_id=p.id AND status IN ('awaiting_payment','under_review','paid'); IF o IS NOT NULL THEN RETURN o; END IF; INSERT INTO public.bot_orders(user_id,product_id,product_name,amount) VALUES(auth.uid(),p.id,p.name,p.price) ON CONFLICT DO NOTHING RETURNING id INTO o; IF o IS NULL THEN SELECT id INTO o FROM public.bot_orders WHERE user_id=auth.uid() AND product_id=p.id AND status IN ('awaiting_payment','under_review','paid'); END IF; INSERT INTO public.bot_audit(actor,action,details) VALUES(auth.uid(),'order_created',jsonb_build_object('order',o)); RETURN o; END $$;
REVOKE ALL ON FUNCTION public.create_bot_order(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.create_bot_order(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.submit_bot_payment(_order uuid,_method uuid,_reference text,_proof text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.bot_orders; m public.payment_methods; BEGIN SELECT * INTO o FROM public.bot_orders WHERE id=_order AND user_id=auth.uid() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Order not found'; END IF; IF o.status='under_review' THEN RETURN; END IF; IF o.status<>'awaiting_payment' THEN RAISE EXCEPTION 'Order cannot accept payment'; END IF; SELECT * INTO m FROM public.payment_methods WHERE id=_method AND enabled AND (address IS NOT NULL OR qr_image_url IS NOT NULL); IF NOT FOUND OR length(trim(_reference))<3 THEN RAISE EXCEPTION 'Valid payment method and reference required'; END IF; IF _proof IS NOT NULL AND (_proof NOT LIKE auth.uid()::text || '/' || _order::text || '/%' OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='bot-order-proofs' AND name=_proof)) THEN RAISE EXCEPTION 'Invalid proof'; END IF; INSERT INTO public.bot_payment_submissions(order_id,method_id,method_name,transaction_reference,proof_path) VALUES(o.id,m.id,m.name,trim(_reference),_proof); UPDATE public.bot_orders SET status='under_review' WHERE id=o.id; INSERT INTO public.bot_audit(actor,action,details) VALUES(auth.uid(),'payment_submitted',jsonb_build_object('order',o.id)); END $$;
REVOKE ALL ON FUNCTION public.submit_bot_payment(uuid,uuid,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.submit_bot_payment(uuid,uuid,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.review_bot_order(_order uuid,_status text,_reason text DEFAULT '') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.bot_orders; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; SELECT * INTO o FROM public.bot_orders WHERE id=_order FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Order not found'; END IF; IF _status=o.status THEN RETURN; END IF; IF NOT ((o.status='under_review' AND _status IN ('paid','rejected')) OR (o.status='paid' AND _status='refunded')) THEN RAISE EXCEPTION 'Invalid status change'; END IF; IF _status IN ('rejected','refunded') AND length(trim(_reason))=0 THEN RAISE EXCEPTION 'Reason required'; END IF; UPDATE public.bot_orders SET status=_status,reason=nullif(_reason,''),paid_at=CASE WHEN _status='paid' THEN now() ELSE paid_at END WHERE id=o.id; IF _status='paid' THEN INSERT INTO public.bot_entitlements(order_id,user_id,product_id) VALUES(o.id,o.user_id,o.product_id) ON CONFLICT DO NOTHING; ELSE UPDATE public.bot_entitlements SET revoked=true WHERE order_id=o.id; END IF; INSERT INTO public.bot_audit(actor,action,details) VALUES(auth.uid(),'order_'||_status,jsonb_build_object('order',o.id,'reason',_reason)); END $$;
REVOKE ALL ON FUNCTION public.review_bot_order(uuid,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.review_bot_order(uuid,text,text) TO authenticated;
CREATE POLICY bot_file_admin ON storage.objects FOR ALL TO authenticated USING(bucket_id='bot-files' AND public.has_role(auth.uid(),'admin')) WITH CHECK(bucket_id='bot-files' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY bot_proof_owner_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='bot-order-proofs' AND (storage.foldername(name))[1]=auth.uid()::text AND EXISTS(SELECT 1 FROM public.bot_orders WHERE id::text=(storage.foldername(name))[2] AND user_id=auth.uid() AND status='awaiting_payment'));
CREATE POLICY bot_proof_owner_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='bot-order-proofs' AND ((storage.foldername(name))[1]=auth.uid()::text OR public.has_role(auth.uid(),'admin')));
CREATE OR REPLACE FUNCTION public.authorize_bot_download(_order uuid,_user uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o public.bot_orders; f public.bot_file_metadata; lim integer; BEGIN SELECT * INTO o FROM public.bot_orders WHERE id=_order AND user_id=_user AND status='paid' FOR UPDATE; IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.bot_entitlements WHERE order_id=o.id AND user_id=_user AND product_id=o.product_id AND NOT revoked) OR EXISTS(SELECT 1 FROM public.account_access WHERE user_id=_user AND suspended) THEN RAISE EXCEPTION 'Download not authorized'; END IF; SELECT download_limit INTO lim FROM public.bot_products WHERE id=o.product_id; IF lim>0 AND (SELECT count(*) FROM public.bot_download_logs WHERE order_id=o.id)>=lim THEN RAISE EXCEPTION 'Download limit reached'; END IF; SELECT * INTO f FROM public.bot_file_metadata WHERE product_id=o.product_id; IF NOT FOUND THEN RAISE EXCEPTION 'File unavailable'; END IF; INSERT INTO public.bot_download_logs(order_id,user_id) VALUES(o.id,_user); INSERT INTO public.bot_audit(actor,action,details) VALUES(_user,'download_authorized',jsonb_build_object('order',o.id)); RETURN jsonb_build_object('path',f.path,'filename',f.filename); END $$;
REVOKE ALL ON FUNCTION public.authorize_bot_download(uuid,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.authorize_bot_download(uuid,uuid) TO service_role;